import { compareSemver, SEMVER_RE } from "@capybara-hq/plugin-tools/release";
import type { Finding } from "./source.js";

/** The plugin SDK's public API report (generated by `pnpm gen:sdk-api`), relative to the repo root. */
export const SDK_API_REPORT = "packages/plugin-sdk/api/plugin-sdk.api.md";

const SDK_PACKAGE = "@capybara-hq/plugin-sdk";
const SDK_KEY = /^\s*(["']?)@capybara-hq\/plugin-sdk\1\s*:/;

/** Whether a changeset's frontmatter (between the leading `---` lines) names the plugin SDK. */
export function changesetBumpsSdk(content: string): boolean {
  const lines = content.split(/\r?\n/);
  if (lines[0]?.trim() !== "---") return false;
  for (const line of lines.slice(1)) {
    if (line.trim() === "---") return false;
    if (SDK_KEY.test(line)) return true;
  }
  return false;
}

const VERSION_LINE = /^export const SDK_VERSION = "([^"]*)";$/m;

/** Whether `head` is a higher semver than `base`. */
function raised(v: { base: string; head: string }): boolean {
  return SEMVER_RE.test(v.base) && SEMVER_RE.test(v.head) && compareSemver(v.head, v.base) > 0;
}

/** The two reports differ only in the `SDK_VERSION` line, which now names `version`. */
function onlyVersionLine(reports: { base: string; head: string }, version: string): boolean {
  if (VERSION_LINE.exec(reports.head)?.[1] !== version) return false;
  const strip = (r: string) => r.replace(VERSION_LINE, "");
  return strip(reports.base) === strip(reports.head);
}

/**
 * PR check: when the SDK API report changed, some changeset added in the same diff must bump
 * `@capybara-hq/plugin-sdk` (frontmatter only; a mention in the body doesn't count).
 *
 * `changedFiles` and the keys of `addedChangesets` are repo-relative paths. `reportAtBase: false`
 * (the report does not exist at the base commit) skips the check: the PR that introduces the
 * report has no earlier API to compare against.
 *
 * Versions set without a changeset (`sdkVersions`: the SDK's package.json version at the base and
 * now) also pass when the version was raised (a Version Packages PR: `changeset version` consumed
 * the changeset, and `pnpm version-packages` rewrote `SDK_VERSION` and the report), or when the
 * only change to the report is its `SDK_VERSION` line following package.json (`reports`), such as
 * the first release set by hand to `0.1.0-rc.0` over an unreleased `0.1.0`.
 */
export function checkSdkApiChangeset(
  changedFiles: readonly string[],
  addedChangesets: ReadonlyMap<string, string>,
  opts: {
    reportAtBase?: boolean;
    sdkVersions?: { base: string; head: string };
    reports?: { base: string; head: string };
  } = {},
): Finding[] {
  if (opts.reportAtBase === false) return [];
  if (!changedFiles.includes(SDK_API_REPORT)) return [];
  const v = opts.sdkVersions;
  if (v !== undefined && v.base !== v.head) {
    if (raised(v)) return [];
    if (opts.reports !== undefined && onlyVersionLine(opts.reports, v.head)) return [];
  }
  for (const content of addedChangesets.values()) {
    if (changesetBumpsSdk(content)) return [];
  }
  return [
    {
      file: SDK_API_REPORT,
      line: 1,
      rule: "sdk-api-changeset",
      message: `the plugin SDK public API changed but no added changeset bumps "${SDK_PACKAGE}"; run pnpm changeset and select ${SDK_PACKAGE}`,
    },
  ];
}
